#include "vwap.hpp"
#include <cmath>
#include <stdexcept>
#include <sstream>
#include <iomanip>
namespace vwap {
static bool date(const std::string& s){if(s.size()!=10||s[4]!='-'||s[7]!='-')return false;for(int i=0;i<10;++i)if(i!=4&&i!=7&&(s[i]<'0'||s[i]>'9'))return false;int y=std::stoi(s.substr(0,4)),m=std::stoi(s.substr(5,2)),d=std::stoi(s.substr(8,2));if(y<1||m<1||m>12)return false;int days[]={31,28,31,30,31,30,31,31,30,31,30,31};if(y%4==0&&(y%100!=0||y%400==0))days[1]=29;return d>=1&&d<=days[m-1];}
static void require(bool b,const char* why){if(!b)throw std::invalid_argument(why);}
Series calculate(const std::vector<Point>& input,const Params& p){bool actual=p.mode=="actual-amount",session=p.anchor=="session",cumulative=p.quantities=="cumulative";require(actual||p.mode=="legacy-close-approx"||p.mode=="hlc3-approx","unsupported VWAP mode");require(session||p.anchor=="loaded-window","unsupported VWAP anchor");require(p.period=="intraday"||p.period=="day"||p.period=="week"||p.period=="month"||p.period=="year","unsupported period");require(!session||p.period=="intraday"||p.period=="day","aggregated multi-day bars cannot be session VWAP");require(session||!p.anchorId.empty(),"loaded window requires explicit actual anchor ID");require(p.quantities=="incremental"||cumulative,"quantity semantics must be declared");require(!cumulative||(actual&&session),"cumulative quantities only support actual session ratio; do not double-sum");
Series out;out.approximate=!actual;out.values.assign(input.size(),missing());out.reasons.assign(input.size(),"unavailable");out.provisional.assign(input.size(),false);out.breakBefore.assign(input.size(),true);out.label=actual?"真实成交金额/成交量均价":p.mode=="hlc3-approx"?"HLC3×量近似VWAP":"旧收盘价×量近似VWAP";out.label+=session?" · 按交易日":" · 明确加载窗口 "+p.anchorId;out.explanation=actual?"需匹配金额/成交量期间、明确CNY及股数换算、未复权价格；无金额或单位不明不回退。":"价格×成交量权重估计，不是真实成交均价；旧代码默认close而非HLC3。";out.explanation+=" 缺失观察不补0；区间缺数后不跳过误算。仅使用当前及此前输入。";auto scale=[](double n){if(!std::isfinite(n))return std::string("未知");std::ostringstream s;s<<std::setprecision(15)<<n;return s.str();};out.explanation+=" 原量单位："+p.volumeUnit+"；数量口径："+p.quantities+"；价格口径："+p.priceBasis+"。";if(actual)out.explanation+=" 原量×"+scale(p.volumeToShares)+"=股，原金额×"+scale(p.amountToCny)+"=CNY（均由来源合同声明）。";out.coverage=p.coversFromOpen?"来源声明从开盘覆盖；完整性仍以源记录为准":"从当前提供范围计算，不声称全日完整覆盖";
bool knownUnit=!p.volumeUnit.empty()&&p.volumeUnit!="unknown"&&p.volumeUnit!="未知";bool unit=knownUnit&&(!actual||(std::isfinite(p.volumeToShares)&&p.volumeToShares>0&&std::isfinite(p.amountToCny)&&p.amountToCny>0));double sumV=0,sumA=0,lastV=-1,lastA=-1;bool tainted=false;std::string day;std::int64_t previous=-1;
for(std::size_t i=0;i<input.size();++i){const auto& x=input[i];bool newDay=session&&date(x.session)&&x.session!=day;if(newDay){day=x.session;sumV=sumA=0;lastV=lastA=-1;tainted=false;}out.breakBefore[i]=i==0||(session&&p.period=="intraday"&&newDay)||!std::isfinite(out.values[i-1]);out.provisional[i]=!x.closed&&!x.axisGap;auto fail=[&](std::string reason){out.reasons[i]=reason;if(!cumulative)tainted=true;};if(x.time<0||x.time<=previous){fail("missing-or-unordered-time");continue;}previous=x.time;if(x.axisGap){out.reasons[i]="axis-gap-not-observation";continue;}if(session&&!date(x.session)){fail("missing-session-date");continue;}if(!unit){fail("quantity-unit-unknown");continue;}if(actual&&p.priceBasis!="unadjusted"){fail("actual-price-basis-not-unadjusted");continue;}if(!x.valid){fail("invalid-observation");continue;}if(!std::isfinite(x.volume)||x.volume<0){fail("missing-or-negative-volume");continue;}if(actual&&(!std::isfinite(x.amount)||x.amount<0)){fail("missing-or-negative-amount");continue;}if(tainted){out.reasons[i]=cumulative?"earlier-cumulative-reset":"earlier-observation-gap";continue;}double volume=x.volume*(actual?p.volumeToShares:1),amount=0;if(!std::isfinite(volume)){fail("quantity-overflow");continue;}if(actual){amount=x.amount*p.amountToCny;if(!std::isfinite(amount)||(volume==0&&amount!=0)||(volume>0&&amount==0)){fail("amount-volume-inconsistent");continue;}}else if(volume>0){double price=x.close;if(p.mode=="hlc3-approx"){if(!std::isfinite(x.high)||!std::isfinite(x.low)||x.low<=0||x.high<x.low||x.close<x.low||x.close>x.high){fail("missing-or-invalid-hlc3");continue;}price=x.high/3+x.low/3+x.close/3;}if(!std::isfinite(price)||price<=0){fail("missing-or-invalid-price");continue;}amount=price*volume;if(!std::isfinite(amount)){fail("quantity-overflow");continue;}}
if(cumulative){if((lastV>=0&&volume<lastV)||(lastA>=0&&amount<lastA)){out.reasons[i]="cumulative-decrease";tainted=true;continue;}lastV=volume;lastA=amount;sumV=volume;sumA=amount;}else{sumV+=volume;sumA+=amount;if(!std::isfinite(sumV)||!std::isfinite(sumA)){fail("cumulative-overflow");continue;}}if(sumV<=0){out.reasons[i]="zero-total-volume";continue;}double value=sumA/sumV;if(!std::isfinite(value)||value<=0){fail("invalid-ratio");continue;}out.values[i]=value;out.reasons[i]=volume==0?"known-zero-volume":actual?"actual-amount-ratio":"price-volume-approximation";}
return out;}
std::string explain(const Series& s,std::size_t i){if(i>=s.values.size())return "时点不存在";std::ostringstream text;text<<s.label<<"\n"<<s.coverage<<"\n"<<s.explanation<<"\n当前状态："<<s.reasons[i];if(std::isfinite(s.values[i]))text<<"\n数值："<<std::fixed<<std::setprecision(4)<<s.values[i];else text<<"\n数值：未知";if(s.provisional[i])text<<"\n未闭合时段，数值可随源记录更新";text<<"\n价格相对该线仅为描述，不构成买卖信号或验证完成。";return text.str();}
}
